DROP TABLE IF EXISTS `cards`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `cards` (
  `id` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `deck_id` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `front` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `back` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `hint` text COLLATE utf8mb4_unicode_ci,
  `position` int NOT NULL DEFAULT '0',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `source_card_id` char(36) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `front_image` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `back_image` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_cards_deck_position` (`deck_id`,`position`),
  KEY `idx_cards_source_card` (`source_card_id`),
  CONSTRAINT `fk_cards_deck` FOREIGN KEY (`deck_id`) REFERENCES `decks` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
