--
-- Table structure for table `decks`
--

DROP TABLE IF EXISTS `decks`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `decks` (
  `id` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `user_id` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `group_id` char(36) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `library_deck_id` char(36) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `name` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL,
  `description` text COLLATE utf8mb4_unicode_ci,
  `front_language` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'en-US',
  `back_language` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'en-US',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `class_source_deck_id` char(36) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `class_synced_at` timestamp NULL DEFAULT NULL,
  `source_share_id` char(36) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_decks_user_library` (`user_id`,`library_deck_id`),
  KEY `idx_decks_user` (`user_id`),
  KEY `idx_decks_group` (`group_id`),
  KEY `fk_decks_library_deck` (`library_deck_id`),
  KEY `idx_decks_user_class_source` (`user_id`,`class_source_deck_id`),
  KEY `idx_decks_user_source_share` (`user_id`,`source_share_id`),
  CONSTRAINT `fk_decks_group` FOREIGN KEY (`group_id`) REFERENCES `deck_groups` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_decks_library_deck` FOREIGN KEY (`library_deck_id`) REFERENCES `library_decks` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_decks_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

