  `study_order` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'POSITION',
  `study_scope` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'DUE_ONLY',
  `restudy_wait` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'ONE_DAY',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `pro_licensed` tinyint(1) NOT NULL DEFAULT '0',
  `admin` tinyint(1) NOT NULL DEFAULT '0',
  `teacher_mode` tinyint(1) NOT NULL DEFAULT '0',
  `stripe_customer_id` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `pro_expires_at` timestamp NULL DEFAULT NULL,
  `agent_included_credits` int NOT NULL DEFAULT '0',
  `agent_addon_credits` int NOT NULL DEFAULT '0',
  `agent_credit_period` char(7) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `email_verified` tinyint(1) NOT NULL DEFAULT '1',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_users_email` (`email`),
  UNIQUE KEY `uk_users_google_sub` (`google_sub`),
  UNIQUE KEY `uk_users_stripe_customer` (`stripe_customer_id`)
